/**
 * ====================================================================
 * BIRTHDAY SURPRISE CONFIGURATION
 * ====================================================================
 * Customize everything here without touching the components:
 * - Recipient's name and subtitle
 * - Background music file path
 * - Personal heartfelt letter and cinematic quotes
 * - Theme colors (rose, champagne, dark background)
 */

export const birthdayConfig = {
  // Person being celebrated
  name: "Nisha Choudhary",
  nickname: "Nisha",
  birthdayDate: "Special Day",

  // Section 1: Intro texts
  intro: {
    eyebrow: "FOR SOMEONE SPECIAL",
    title: "A little surprise...",
    subtitle: "Made with a few memories, a little music, and a lot of love.",
    buttonText: "Open the surprise",
  },

  // Section 2: Birthday reveal
  reveal: {
    eyebrow: "Today is a little more special...",
    headline: "HAPPY BIRTHDAY",
    subtitle: "Here's to another beautiful year of memories.",
  },

  // Section 3: Memories headline
  memoriesHeader: {
    title: "MEMORIES",
    subtitle: "A few moments worth keeping forever.",
    hint: "Hover or tap on photographs to pause & admire",
  },

  // Section 4: Cinematic quote break
  quotes: [
    "Some moments become memories.",
    "Some memories become stories.",
    "And some people become unforgettable.",
  ],

  // Section 5: Personal intimate letter
  personalMessage: {
    eyebrow: "FROM MY HEART",
    heading: "A little something for you.",
    handwrittenAccent: "always and forever",
    paragraphs: [
      "Through all the little moments, the quiet laughter that caught us off guard, the random late-night conversations, and the warmth we've shared along the way...",
      "You bring an effortless light into every room you step into. The kindness you carry and the quiet grace you have inspires everyone around you more than you know.",
      "On this day, I hope you pause to see how truly loved and cherished you are. May this year bring you gentle mornings, adventures that take your breath away, and dreams quietly unfolding into reality.",
    ],
    signoff: "With all my love & gratitude,",
    authorName: "Yours always",
  },

  // Section 6: Final celebration
  final: {
    eyebrow: "AND FINALLY...",
    headline: "HAPPY BIRTHDAY",
    nameHeart: "Nisha Choudhary ❤️",
    wish: "May this year be your most beautiful one yet.",
    replayText: "Replay the journey",
  },

  // Music configuration
  // Place your audio file in public/music/birthday.mp3
  // If the file is not found, the website will smoothly use an ambient harmonic melody!
  music: {
    audioSrc: "/music/birthday.mp3",
    trackTitle: "Soft Piano & Strings",
    autoScrollAfterOpen: true,
  },

  // Elegant luxury palette tokens
  theme: {
    bgDark: "#08070B",
    bgCard: "rgba(22, 19, 28, 0.65)",
    textPrimary: "#FAF7F5",
    textMuted: "#B8B0B8",
    accentRose: "#E2A499",
    accentBlush: "#F6D5CD",
    accentChampagne: "#E8D8C8",
    glowPink: "rgba(226, 164, 153, 0.22)",
    borderGlass: "rgba(246, 213, 205, 0.15)",
  },
};

export default birthdayConfig;
